{
  "StartAt": "Fan Out",
  "States": {
    "Fan Out": {
      "Type": "Map",
      "ItemsPath": "$.accounts",
      "ItemSelector": {
        "accountId.$": "$$.Map.Item.Value.id",
        "region.$": "$.region"
      },
      "ItemProcessor": {
        "ProcessorConfig": {
          "Mode": "DISTRIBUTED",
          "ExecutionType": "STANDARD"
        },
        "StartAt": "Sync Account",
        "States": {
          "Sync Account": {
            "Type": "Task",
            "Resource": "arn:aws:states:::states:startExecution.sync:2",
            "Parameters": {
              "StateMachineArn": "arn:aws:states:us-east-1:123456789012:stateMachine:SyncAccount",
              "Input": {
                "accountId.$": "$.accountId",
                "region.$": "$.region"
              }
            },
            "End": true
          }
        }
      },
      "Retry": [
        {
          "ErrorEquals": [
            "States.ALL"
          ],
          "MaxAttempts": 1
        }
      ],
      "Next": "Approve"
    },
    "Approve": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sqs:sendMessage.waitForTaskToken",
      "Parameters": {
        "QueueUrl": "https://sqs.us-east-1.amazonaws.com/123/approvals",
        "MessageBody": {
          "token.$": "$$.Task.Token",
          "summary.$": "States.Format('Synced {}', $.region)"
        }
      },
      "HeartbeatSeconds": 600,
      "Retry": [
        {
          "ErrorEquals": [
            "Throttled"
          ],
          "IntervalSeconds": 1,
          "MaxAttempts": 5
        },
        {
          "ErrorEquals": [
            "States.Timeout"
          ],
          "MaxAttempts": 0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": [
            "Rejected"
          ],
          "Next": "Rejected"
        },
        {
          "ErrorEquals": [
            "States.ALL"
          ],
          "Next": "Rejected"
        }
      ],
      "Next": "Route"
    },
    "Route": {
      "Type": "Choice",
      "Choices": [
        {
          "Variable": "$.decision",
          "StringMatches": "auto-*",
          "Next": "Wait Until"
        },
        {
          "Variable": "$.decision",
          "IsPresent": false,
          "Next": "Rejected"
        }
      ],
      "Default": "Wait Until"
    },
    "Wait Until": {
      "Type": "Wait",
      "Timestamp": "2026-12-01T09:30:00Z",
      "Next": "Dynamic Wait"
    },
    "Dynamic Wait": {
      "Type": "Wait",
      "SecondsPath": "$.delaySeconds",
      "End": true
    },
    "Rejected": {
      "Type": "Pass",
      "End": true
    }
  }
}
